class Solution {
    private String s;
    private int n;
    private List<String> res = new ArrayList<>();
    private List<String> path = new ArrayList<>();

    public List<String> restoreIpAddresses(String s) {
        this.s = s;
        this.n = s.length();
        if (n >= 4 && n <= 12) dfs(0);
        return res;
    }

    private void dfs(int start) {
        if (path.size() == 4) {
            if (start == n) res.add(String.join(".", path));
            return;
        }
        for (int i = start; i < Math.min(start + 3, n); i++) {
            if (!ok(start, i)) break;
            path.add(s.substring(start, i + 1));
            dfs(i + 1);
            path.remove(path.size() - 1);
        }
    }

    private boolean ok(int a, int b) {
        if (b - a + 1 > 3) return false;
        if (b - a + 1 > 1 && s.charAt(a) == '0') return false;
        return Integer.parseInt(s.substring(a, b + 1)) <= 255;
    }
}

